  cmd.Clear();cmd.SetComputeIntParam(shader,"_SamplingCount",1);cmd.SetComputeIntParams(shader,"_SamplingPixel",16,12);cmd.SetComputeIntParam(shader,"_CSMOutputWidth",w);cmd.SetComputeIntParam(shader,"_CSMOutputHeight",h);cmd.SetComputeIntParam(shader,"_CSMFrameIndex",test==9?4:1);
