  cmd.SetComputeTextureParam(shader,k,"_VSMHistoryPrevious",signal);cmd.SetComputeTextureParam(shader,k,"_VSMDepthPrevious",depth);cmd.SetComputeBufferParam(shader,k,"_SamplingInputs",input);cmd.SetComputeBufferParam(shader,k,"_SamplingNormals",normal);cmd.SetComputeBufferParam(shader,k,"_SamplingResults",output);cmd.DispatchCompute(shader,k,1,1,1);Graphics.ExecuteCommandBuffer(cmd);
  var values=new Vector2[1];output.GetData(values);float expectedCount=test==0||test==10?2:4;bool expectedValid=!(test>=2&&test<=4||test>=6&&test<=8);
  if(values[0].y!=expectedCount||(values[0].x>=0)!=expectedValid)throw new Exception("case="+test+" result="+values[0]);
  report+="case="+test+" mean="+values[0].x+" rays="+values[0].y+"\n";
 }
 File.WriteAllText("Packages/VividRP/Temp~/vsm-temporal/history-gpu.txt",report+"passed=12");result.Log(report+"passed=12");
